python3 - <<'PY'
# specialization guard: consult the marker instead of sniffing Mixed
p='src/types/checker/functions/resolution/specialization.rs'
s=open(p).read()
old = """                let by_ref_widened = by_ref_param
                    && match param_types[seen_idx].1.codegen_repr() {
                        PhpType::Array(elem) => elem.codegen_repr() == PhpType::Mixed,
                        PhpType::AssocArray { value, .. } => {
                            value.codegen_repr() == PhpType::Mixed
                        }
                        _ => false,
                    };"""
new = """                let by_ref_widened = by_ref_param
                    && self
                        .by_ref_widened_params
                        .contains(&(name.to_string(), seen_idx));"""
assert s.count(old)==1
open(p,'w').write(s.replace(old,new))

# method pass: record the marker
p2='src/types/checker/method_pass.rs'
s2=open(p2).read()
old2 = """        for (index, exit_ty) in widened {
            let Some((_, param_ty)) = sig.params.get_mut(index) else {
                continue;
            };
            if crate::types::checker::array_element_representation_changes(param_ty, &exit_ty) {
                *param_ty = exit_ty;
            }
        }
    }"""
new2 = """        let mut recorded = Vec::new();
        for (index, exit_ty) in widened {
            let Some((_, param_ty)) = sig.params.get_mut(index) else {
                continue;
            };
            if crate::types::checker::array_element_representation_changes(param_ty, &exit_ty) {
                *param_ty = exit_ty;
                recorded.push(index);
            }
        }
        let owner = format!("{}::{}", class.name, key);
        for index in recorded {
            self.by_ref_widened_params.insert((owner.clone(), index));
        }
    }"""
assert s2.count(old2)==1
open(p2,'w').write(s2.replace(old2,new2))
print('marker wired for both passes')
